\label{modularhyperbola_theorem} Let $q$ be a prime, let $a \in (\mathbb{Z}/q\mathbb{Z})^{\times}$ and let $\mu_{a,q,d}= (q-1)^{-(d-1)} \sum_{s \in S_{a,q,d}} \delta_s$ denote the empirical measure of the set $S_{a,q,d}$. If $d=2$, then
\begin{equation}\label{W2estimated=2}
W_2 (\mu_{a,q,2}, \mathrm{Vol}) \ll (\log q)^{1/2} q^{-1/2}
\end{equation}
with a universal implied constant. If $d \ge 3$, then
\[ W_2(\mu_{a,q,d}, \mathrm{Vol}) \asymp q^{-(d-1)/d} \quad \textrm{and} \quad D_2 (\mu_{a,q,d}, \mathrm{Vol}) \asymp q^{-1} \]
with implied constants that depend only on $d$.

\label{cassels_lemma} Let $\alpha_1, \alpha_2, \ldots, \alpha_m \in \mathbb{R}^d$, let $N_1, N_2, \ldots, N_m \ge 2$ be integers and let $N=N_1 N_2 \cdots N_m$. Under the assumption \eqref{diophantinelattice}, every axis-parallel cube in $\mathbb{R}^d / \mathbb{Z}^d$ of sidelength
\[ \frac{((d+m)!)^2}{2^{d+m-1} \psi^{-1} \left( 2^{(d+m-2)m} ((d+m)!)^{-2m} I N \right)} \]
contains at least one point from the set
\begin{equation}\label{latticeset}
\left\{ n_1 \alpha_1 + n_2 \alpha_2 + \cdots + n_m \alpha_m + \mathbb{Z}^d : n_1 \in [1, N_1], \,\, n_2 \in [1, N_2], \,\, \ldots, \,\, n_m \in [1,N_m] \right\} .
\end{equation}
